+  } else {
+    spell_checker = to_aspell_speller(possible_err);
+  }
+  int correct = aspell_speller_check(spell_checker, (const char *)test_word, -1);
+  if (!correct) {
+    fprintf(stderr, "%s", "fail: expected word to be correct\n");
